/** A bundle is budgeted before any round runs, so its residue is a round-0 row. */
const PRE_LOOP_ROUND = 0;

/**
 * The bundle's residue rides the run's OWN row channel: `src/bench/metrics.ts` counts
 * ledger residue rows, so evidence a cap discarded is measurable across runs instead of
 * living only in a paragraph a human must read. Each row names its run and stage: the per-spec
 * ledger outlives every run that appends to it, and a later run must not read this one's cut back.
 */
export interface LedgerResidueTarget {
  readonly pipelineDir: string;
  readonly runId: string;
  readonly stage: string;
}

export const appendLedgerResidue = (
  target: LedgerResidueTarget,
  entries: readonly ResidueEntry[],
  now: () => string
): void => {
  if (entries.length === 0) return;
  const file = path.join(target.pipelineDir, LEDGER_FILE);
  mkdirSync(path.dirname(file), { recursive: true });
  const stamp = { runId: target.runId, stage: target.stage };
  const rows = entries
    .map(entry => `${JSON.stringify({ at: now(), round: PRE_LOOP_ROUND, kind: 'residue', ...stamp, entry })}\n`)
    .join('');
  appendFileSync(file, rows, 'utf8');
};

