const capEdges = (edges: readonly EnumeratedEdge[], cap: number): CappedEdges => {
  const overflow = edges.slice(cap);
  return {
    edges: edges.slice(0, cap),
    dropped: { total: overflow.length, byDimension: countByDimension(overflow) },
  };
};

/**
 * Over-cap names the loss AND its remedy: a larger spec whose edges go unjudged is the
 * failure the cap must not hide, so the entry recommends splitting rather than accepting it.
 */
type EdgeSource = 'enumerated' | 'provider';

/** F-153. Each source's cut names who produced the edges it dropped. */
const SOURCE_TEXT: Readonly<Record<EdgeSource, string>> = {
  enumerated: 'enumerated edge(s) are not in the bundle — the enumerators produced',
  provider: `${PROVIDER_ENUMERATOR} candidate edge(s) are not in the bundle — the knowledge provider returned`,
};

interface EdgeCut {
  readonly source: EdgeSource;
  readonly dropped: DroppedEvidence;
  readonly cap: number;
}

const overCapText = (cut: EdgeCut): string =>
  `${String(cut.dropped.total)} ${SOURCE_TEXT[cut.source]} more ` +
  `than fit under the ${String(cut.cap)}-edge cap, so those edges carry no critic verdict. Split this feature into ` +
  `smaller specs instead of accepting the loss: a bigger spec whose parts go unjudged is the worse outcome.`;

const edgeResidue = (cut: EdgeCut, artifact: Artifact): readonly ResidueEntry[] =>
  cut.dropped.total === 0
    ? []
    : [
        {
          class: 'bundle-over-cap',
          anchor: { artifact, jsonPath: sectionAnchor('candidate-edges') },
          findingIds: [],
          text: overCapText(cut),
          dropped: cut.dropped,
        },
      ];

