import { GoalsDocSchema } from '../stages/index.js';

/**
 * The goal document has exactly one writer. Every downstream citation key comes from
 * here, so the projection is re-validated rather than trusted: a resolve output that
 * drifted from the schema fails at emission, where the producing stage is still known.
 */
export const buildGoalsDoc = (output: SpecResolveOutput): GoalsDoc =>
  GoalsDocSchema.parse({
    schemaVersion: output.goals.schemaVersion,
    goals: output.goals.goals,
    nonGoals: output.goals.nonGoals,
  });

const INDENT = 2;

/** Key order is fixed by the projection above, so the same input yields identical bytes. */
export const renderGoalsJson = (output: SpecResolveOutput): string =>
  `${JSON.stringify(buildGoalsDoc(output), null, INDENT)}\n`;

