import { GoalsDocSchema, ResolutionDocSchema } from '../../../shared/ir/index.js';
import { SchemaVersionSchema } from './common.js';

/**
 * SPEC-A output: the goal set, and the noun -> surface resolution plus the drift table
 * that the current-state document is rendered from.
 */

// The goal-set and resolution grammars live in the shared IR module; this stage is their
// origin, and what it keeps is the writer-facing output envelope and its manifest ref.
export type {
  DriftStatus,
  GoalEntry,
  GoalsDoc,
  GoalSet,
  NonGoalEntry,
  ResolutionDoc
} from '../../../shared/ir/index.js';
export {
  DRIFT_STATUSES,
  DriftEntrySchema,
  GoalEntrySchema,
  GoalsDocSchema,
  GoalSetSchema,
  MappingEntrySchema,
  NonGoalEntrySchema,
  refineMappingGrain,
  ResolutionDocSchema,
  SHAPE_KINDS,
  SURFACE_KINDS
} from '../../../shared/ir/index.js';

/**
 * The PLAN-side repair stage that recovers a goal set for a spec dir produced outside the
 * pipeline. Its ref lives beside the contract it validates against, because the repair restates
 * the shipped goal contract rather than forking one: the stage emits the set, the projection
 * stamps the version, and `goals.json` keeps exactly one shape.
 */
export const GOALS_EXTRACT_SCHEMA_REF = 'stage/plan/goals-extract';

/** One stage, two documents: the resolve step emits the goal set and the resolution together. */
export const SpecResolveOutputSchema = z
  .object({ schemaVersion: SchemaVersionSchema, goals: GoalsDocSchema, resolution: ResolutionDocSchema })
  .readonly();

export type SpecResolveOutput = Readonly<z.infer<typeof SpecResolveOutputSchema>>;

